INSERT INTO p_amb_section (id, act_id, name, line, icon, icon_svg, color, enabled, pinned, sort) VALUES ('fbe68795d3f14e19', 'brand_speedin', 'Hair, skin, nails', 'The daily beauty step you will not skip. Hair Skin & Nails.', 'sparkles', '<path d="M11.017 2.814a1 1 0 0 1 1.966 0l1.051 5.558a2 2 0 0 0 1.594 1.594l5.558 1.051a1 1 0 0 1 0 1.966l-5.558 1.051a2 2 0 0 0-1.594 1.594l-1.051 5.558a1 1 0 0 1-1.966 0l-1.051-5.558a2 2 0 0 0-1.594-1.594l-5.558-1.051a1 1 0 0 1 0-1.966l5.558-1.051a2 2 0 0 0 1.594-1.594z"/><path d="M20 2v4"/><path d="M22 4h-4"/><circle cx="4" cy="20" r="2"/>', '#BE185D', 1, 0, 4);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('1dabb59f5303dd90', 'brand_speedin', '3406b96aa44127dd', 1, 1, 1, 'live', 'Strip on the tongue in the car', 'The strip going on the tongue in the first second shows the whole product before anyone can scroll.', 'Anyone who drives to work, the gym or school pickup', 'Energy', 'Car selfie, show and tell', '["This little strip replaced my morning energy drink.", "Watch this. No water, no can, nothing.", "I used to buy one of these every single morning."]', '[{"label": "Open · 0 to 3s", "text": "Strip up to the lens, then onto your tongue. Say the first line."}, {"label": "Middle", "text": "Tongue out so we see it melting. Open the pack and show how many are inside. Hold up an old can or cup (no logo facing camera) and say what you used to spend time and sugar on."}, {"label": "Close", "text": "Pack next to your face. Say how your drive or morning felt, in your own words."}]', 'A strip held between two fingers right in front of the lens, then straight onto the tongue', 'Tongue out on camera with the strip half melted, then the can comes out next to the pack', '[{"brand": "NuStrips", "what": "Sit in your parked car, hold a Speedin Energy strip up to the camera, put it on your tongue and show it melting. Then hold up the energy drink can you used to buy and say why you stopped.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('ef76a82b577f711b', 'brand_speedin', '1dabb59f5303dd90', 'upload', 'amb/brand_speedin/inspo-nustrips-car-can.mp4', 'NuStrips (inspiration)', 'Sit in your parked car, hold a Speedin Energy strip up to the camera, put it on your tongue and show it melting. Then hold up the energy drink can you used to buy and say why you stopped.', '3406b96aa44127dd', 1, 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('912102c84e96416e', 'brand_speedin', '3406b96aa44127dd', 1, 2, 2, 'live', 'It is 2:56pm and I know exactly what happens next', 'Everyone knows the 3pm slump, so the clock alone makes people stop.', 'Office workers, work from home parents, students', 'Energy', 'Desk POV, 3pm slump', '["It is 2:56 and I already know how this goes.", "This is the exact moment my day falls apart.", "My 3pm used to mean a second coffee. Not anymore."]', '[{"label": "Open · 0 to 3s", "text": "Over the shoulder at your desk, then turn the laptop so we see the time."}, {"label": "Middle", "text": "Walk toward the coffee maker, stop, come back. Open a strip and put it on your tongue. Say it melts in about 30 seconds, no water."}, {"label": "Close", "text": "Back to typing, or out the door to the next thing. Say what your afternoon feels like now."}]', 'Laptop clock reading 2:56 PM, you looking tired at it', 'You walk to the coffee maker, stop, and turn back to the strip', '[{"brand": "The Patch Remedy", "what": "Film yourself at your desk right before 3pm, point at the clock on your laptop or phone, skip the coffee run and put a Speedin Energy strip on your tongue instead. Then get back to work.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('cae3f339e6eb5718', 'brand_speedin', '912102c84e96416e', 'upload', 'amb/brand_speedin/inspo-patchremedy-3pm-desk.mp4', 'The Patch Remedy (inspiration)', 'Film yourself at your desk right before 3pm, point at the clock on your laptop or phone, skip the coffee run and put a Speedin Energy strip on your tongue instead. Then get back to work.', '3406b96aa44127dd', 1, 1, 2);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('18db261cfd29f2f0', 'brand_speedin', '61450a9ce3dda95a', 1, 3, 3, 'live', 'If you are like me, your brain starts at night', 'A real messy night routine feels like the viewer''s own house.', 'Moms, busy parents, anyone whose mind races at night', 'Sleep', 'Night routine, voiceover', '["If you are like me, your brain turns on the second the kids are asleep.", "My night routine, the real one.", "I used to lie there for an hour. Here is what changed."]', '[{"label": "Open · 0 to 3s", "text": "Bathroom, brushing teeth, first line on screen."}, {"label": "Middle", "text": "Quick clips: kitchen, folding something, couch. Open a Sleep strip and put it on your tongue, say no water and no pills."}, {"label": "Close", "text": "Lights off, you walking to bed. Say how you feel when you wake up, in your words."}]', 'You in the bathroom mirror, toothbrush in mouth, tired face', 'The lights go off and the strip goes on in the dark kitchen or bedroom', '[{"brand": "Winks", "what": "Film your real night routine: brushing teeth, kitchen tidy, couch, then a Speedin Sleep strip on your tongue before lights out. Talk over it like you are telling a friend.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('a5bf119f39fec753', 'brand_speedin', '18db261cfd29f2f0', 'upload', 'amb/brand_speedin/inspo-winks-night-routine.mp4', 'Winks (inspiration)', 'Film your real night routine: brushing teeth, kitchen tidy, couch, then a Speedin Sleep strip on your tongue before lights out. Talk over it like you are telling a friend.', '61450a9ce3dda95a', 1, 1, 3);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('c46760fd6d55749e', 'brand_speedin', '6832e83cd52b3700', 1, 4, 4, 'live', 'My man''s logic: healthy means a mess', 'The mess is funny and makes the strip look easy without saying it.', 'Couples, roommates, siblings', 'Any strip', 'Two person skit', '["My man''s logic: healthy means scoops, spills and cleaning the whole kitchen.", "Every morning I watch this happen.", "He thinks this is the healthy way."]', '[{"label": "Open · 0 to 3s", "text": "Wide shot from the counter, partner mid mess, text on screen."}, {"label": "Middle", "text": "Shaking the shaker, powder on the counter, pill bottles. You step in with the pack."}, {"label": "Close", "text": "Strip on the tongue, partner shrugs, you both walk off. Leave the mess in frame."}]', 'Partner spilling powder everywhere, you watching with a mug, text on top', 'The hand off: you peel a strip and stick it on their tongue', '[{"brand": "Grüns", "what": "Two people, one kitchen. Your partner makes a huge mess with scoops, shakers and pill bottles while you sip your coffee and watch. Then you hand them a Speedin strip.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('509544cf22d610c8', 'brand_speedin', 'c46760fd6d55749e', 'upload', 'amb/brand_speedin/inspo-gruns-couple-skit.mp4', 'Grüns (inspiration)', 'Two people, one kitchen. Your partner makes a huge mess with scoops, shakers and pill bottles while you sip your coffee and watch. Then you hand them a Speedin strip.', '6832e83cd52b3700', 1, 1, 4);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('83b1381143cc5d92', 'brand_speedin', '3406b96aa44127dd', 0, 0, 5, 'live', 'Feeling lazy? A day with the strip', 'Fast cuts of a real life show where the strip fits without a single word of selling.', 'Busy, active creators who can film 5 places in one day', 'Energy', 'Day in my life montage', '["Feeling lazy? Same. Here is my fix.", "Every place this strip came with me today.", "My whole day runs on one tiny strip."]', '[{"label": "Open · 0 to 3s", "text": "Close up of your hands opening the pouch, text on screen."}, {"label": "Middle", "text": "4 or 5 two second clips: car, kitchen, closet, gym, pack in your bag. Strip on the tongue in at least one."}, {"label": "Close", "text": "Pack in your bag or drawer, text: Perform. Recover. Glow."}]', 'Hands peeling the pouch open with text: Feeling lazy?', 'Strip goes on the tongue in the car, then a quick cut to you moving at the gym', '[{"brand": "NuStrips", "what": "Film quick clips of your real day: opening a Speedin Energy strip, putting it on in the car, the gym, getting dressed, the pack in your bag. Short clips, one line of text on each.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('4d865528d09304fd', 'brand_speedin', '83b1381143cc5d92', 'upload', 'amb/brand_speedin/inspo-nustrips-day-montage.mp4', 'NuStrips (inspiration)', 'Film quick clips of your real day: opening a Speedin Energy strip, putting it on in the car, the gym, getting dressed, the pack in your bag. Short clips, one line of text on each.', '3406b96aa44127dd', 1, 1, 5);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('a052b9fe9e120f59', 'brand_speedin', '61450a9ce3dda95a', 0, 0, 6, 'live', 'Lying in bed, talking to camera', 'Filming from the pillow puts the viewer in bed with you at the exact moment they need it.', 'Anyone, great for men and night owls', 'Sleep', 'In bed talking head', '["Brain will not shut off at 2am? Same.", "I used to stare at the ceiling for an hour.", "This is the last thing I do every night."]', '[{"label": "Open · 0 to 3s", "text": "Phone above you, you on the pillow, first line."}, {"label": "Middle", "text": "Show the pack, peel a strip, put it on, keep talking while it melts."}, {"label": "Close", "text": "Say how mornings feel now. Pull the blanket up."}]', 'You lying on your pillow, phone overhead, eyes half closed', 'Strip on the tongue while you are lying down', '[{"brand": "NuStrips", "what": "Lie in bed with the phone above you, talk about the nights you could not switch off, show the Speedin Sleep pack and put a strip on your tongue right there.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('62af99f6ba07a854', 'brand_speedin', 'a052b9fe9e120f59', 'upload', 'amb/brand_speedin/inspo-nustrips-bed-talk.mp4', 'NuStrips (inspiration)', 'Lie in bed with the phone above you, talk about the nights you could not switch off, show the Speedin Sleep pack and put a strip on your tongue right there.', '61450a9ce3dda95a', 1, 1, 6);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('938cb116d7e2c867', 'brand_speedin', 'fbe68795d3f14e19', 0, 0, 7, 'live', 'My hairstylist noticed before I did', 'Someone else noticing is more believable than you saying it.', 'Women who get regular cuts or color', 'Hair Skin & Nails', 'Stylist reaction, then talking head', '["My hairstylist asked me what I changed.", "When your stylist points it out, you know.", "I did not notice until she said it."]', '[{"label": "Open · 0 to 3s", "text": "Salon chair mirror selfie, stylist pointing at your hair."}, {"label": "Middle", "text": "At home, pack in hand. Say you take one Lemon strip every morning, no pills to swallow."}, {"label": "Close", "text": "Back to the salon clip or a hair flip. Say results are different for everyone and this is just you."}]', 'Salon mirror selfie, stylist holding up a section of your hair', 'Back home, you hold up the pack and say what you changed', '[{"brand": "MaryRuth''s", "what": "Film a mirror clip at the salon (or ask your stylist to point at your hair), then cut to you at home holding the Speedin Hair Skin & Nails pack and talking about taking it every day.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('c421021cea72c9b9', 'brand_speedin', '938cb116d7e2c867', 'upload', 'amb/brand_speedin/inspo-maryruth-stylist-growth.mp4', 'MaryRuth''s (inspiration)', 'Film a mirror clip at the salon (or ask your stylist to point at your hair), then cut to you at home holding the Speedin Hair Skin & Nails pack and talking about taking it every day.', 'fbe68795d3f14e19', 1, 1, 7);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('7f5a3e3f9ad0f970', 'brand_speedin', '6832e83cd52b3700', 0, 0, 8, 'live', 'Supplement hacks have gone too far', 'Making fun of the old way makes the new way obvious in 20 seconds.', 'Anyone with a funny face and a cluttered cabinet', 'Any strip', 'Over the top before, simple after', '["Supplement routines have gone too far.", "This is my morning. Every morning.", "Or you could just do this."]', '[{"label": "Open · 0 to 3s", "text": "Extreme close up, handful of pills, text on screen."}, {"label": "Middle", "text": "Struggle: water glass, shaker, gummy jar. Keep it quick and silly."}, {"label": "Close", "text": "Text: or just one strip. Peel, place, smile."}]', 'Your face super close, too many pills in your hand, text: this has gone too far', 'Hard cut to calm you with one strip', '[{"brand": "Hostage Tape", "what": "Close up comedy: line up every pill bottle, powder, shaker and gummy jar you own and struggle through them. Then cut to you peeling one Speedin strip and smiling.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('5c558721cec3f60a', 'brand_speedin', '7f5a3e3f9ad0f970', 'upload', 'amb/brand_speedin/inspo-hostage-hacks-too-far.mp4', 'Hostage Tape (inspiration)', 'Close up comedy: line up every pill bottle, powder, shaker and gummy jar you own and struggle through them. Then cut to you peeling one Speedin strip and smiling.', '6832e83cd52b3700', 1, 1, 8);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('38cc8edae947051d', 'brand_speedin', '3406b96aa44127dd', 0, 0, 9, 'live', 'Trying it for the first time on camera', 'A real first reaction feels honest because it is.', 'Anyone, works best for creators who talk to camera easily', 'Energy', 'Unboxing and first try', '["Okay, these came today and I have no idea what to expect.", "Energy in a strip? Let''s see.", "First time trying this, you are watching it live."]', '[{"label": "Open · 0 to 3s", "text": "Hold the package up and say the first line."}, {"label": "Middle", "text": "Open the box, read the back out loud, peel a strip, put it on your tongue and show it."}, {"label": "Close", "text": "Honest verdict on taste and how long it took to melt. Hold the pack up."}]', 'You holding the mailer bag or box up to the camera, surprised face', 'Tongue out showing the strip, then your reaction to the Strawberry Mint taste', '[{"brand": "NuStrips", "what": "Open your Speedin pack on camera, read what is inside, put your first Energy strip on your tongue and give your honest first reaction to the taste and the melt.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('6db4171686d35ac5', 'brand_speedin', '38cc8edae947051d', 'upload', 'amb/brand_speedin/inspo-nustrips-first-try.mp4', 'NuStrips (inspiration)', 'Open your Speedin pack on camera, read what is inside, put your first Energy strip on your tongue and give your honest first reaction to the taste and the melt.', '3406b96aa44127dd', 1, 1, 9);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('1c3a0f13d37d1e13', 'brand_speedin', '61450a9ce3dda95a', 0, 0, 10, 'live', 'Why I keep this on my nightstand', 'A calm car chat sounds like a tip from a friend, not an ad.', 'Women 30 to 60, anyone who has tried sleep gummies', 'Sleep', 'Car selfie recommendation', '["You need this on your nightstand.", "I stopped keeping a pill bottle by my bed.", "If you have ever woken up groggy, listen."]', '[{"label": "Open · 0 to 3s", "text": "Car selfie, pack up next to your face, first line."}, {"label": "Middle", "text": "Explain the strip: on the tongue, melts in about 30 seconds, no water. Show one strip."}, {"label": "Close", "text": "Say how you wake up now, in your words. End on the pack going on your nightstand."}]', 'You in the driver seat holding the Sleep pack next to your face', 'You compare it to the gummy or pill bottle you used to keep by the bed', '[{"brand": "Rejuvia", "what": "Parked, engine off, hold up the Speedin Sleep pack and explain why it lives on your nightstand: one strip on the tongue at bedtime, no glass of water, no pill bottle.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('918160b8c804ec55', 'brand_speedin', '1c3a0f13d37d1e13', 'upload', 'amb/brand_speedin/inspo-rejuvia-car-sleep.mp4', 'Rejuvia (inspiration)', 'Parked, engine off, hold up the Speedin Sleep pack and explain why it lives on your nightstand: one strip on the tongue at bedtime, no glass of water, no pill bottle.', '61450a9ce3dda95a', 1, 1, 10);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('3420ac3051aeb92a', 'brand_speedin', 'fbe68795d3f14e19', 0, 0, 11, 'live', 'Look at my nails though', 'Nails held to the lens are proof you can see, no before and after needed.', 'Women 35 plus, anyone who has tried a lot of supplements', 'Hair Skin & Nails', 'Selfie testimonial', '["I did not think another supplement would impress me. But look at my nails.", "Two months in and this is the part I did not expect.", "Okay, I have to show you my nails."]', '[{"label": "Open · 0 to 3s", "text": "Kitchen selfie, nails right up to the lens."}, {"label": "Middle", "text": "Hold up the pack, peel a strip, put it on. Say it is one strip a day, no water."}, {"label": "Close", "text": "Hair and nails to camera one more time. Say what you have noticed, only your own experience."}]', 'Your hand coming up to the lens, nails first', 'You run your hand through your hair while talking', '[{"brand": "Obvi", "what": "Selfie in your kitchen. Say you did not expect another supplement to impress you, then hold your nails up to the camera and talk about your Speedin Hair Skin & Nails strips.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('ff3980289a51661f', 'brand_speedin', '3420ac3051aeb92a', 'upload', 'amb/brand_speedin/inspo-obvi-look-at-my-nails.mp4', 'Obvi (inspiration)', 'Selfie in your kitchen. Say you did not expect another supplement to impress you, then hold your nails up to the camera and talk about your Speedin Hair Skin & Nails strips.', 'fbe68795d3f14e19', 1, 1, 11);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('6c318433183e3fe1', 'brand_speedin', '6832e83cd52b3700', 0, 0, 12, 'live', 'Flying with my supplements, TSA edition', 'Travel is the moment pills and powders are most annoying, so the strip wins on sight.', 'Travelers, people who fly for work', 'Any strip', 'Airport vlog', '["Flying with supplements used to be a whole thing.", "Is this TSA friendly? Yep.", "My entire supplement routine fits in my pocket now."]', '[{"label": "Open · 0 to 3s", "text": "Pack sitting on the security bin, your hand grabbing it."}, {"label": "Middle", "text": "Walking to the gate selfie. Show how flat the pack is. Put a strip on, no water."}, {"label": "Close", "text": "In your seat or at the window. Pack in your hand, last line."}]', 'Your bag on the security belt with the Speedin pack on top', 'Strip on the tongue at the gate or in your seat', '[{"brand": "Pure Genius Protein", "what": "Film your trip through the airport: bag on the security belt, walking to the gate, strip out of your pocket. Talk about how strips mean no rattling bottles and no water needed on the plane.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('4e617cf6bba7f5e1', 'brand_speedin', '6c318433183e3fe1', 'upload', 'amb/brand_speedin/inspo-puregenius-airport-tsa.mp4', 'Pure Genius Protein (inspiration)', 'Film your trip through the airport: bag on the security belt, walking to the gate, strip out of your pocket. Talk about how strips mean no rattling bottles and no water needed on the plane.', '6832e83cd52b3700', 1, 1, 12);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('feaf1d3fe140aa18', 'brand_speedin', '3406b96aa44127dd', 0, 0, 13, 'live', '5:30am alarm, new routine', 'The groan at the alarm is relatable before you say a single word.', 'Early shift workers, gym at dawn people, new jobs, parents', 'Energy', 'Early alarm storytime', '["5:30 is now a real time I get up. Who knew.", "Dark mornings, early alarms, new job.", "I am not a morning person. Here is how I fake it."]', '[{"label": "Open · 0 to 3s", "text": "Phone propped on the nightstand. Alarm, groan, hand over your face."}, {"label": "Middle", "text": "Sit up on the bed, talk about your new early schedule, put a strip on your tongue mid sentence."}, {"label": "Close", "text": "Coat on, keys, out the door into the dark."}]', 'You face down in a pillow, alarm going, hand over your face', 'The strip comes out of your pocket while you are still in pajamas', '[{"brand": "Ankhway", "what": "Start in bed with your alarm going off in the dark, then sit on the edge of the bed and talk about your early mornings while you put a Speedin Energy strip on. End walking out the door.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('8a4e6ab55adf3922', 'brand_speedin', 'feaf1d3fe140aa18', 'upload', 'amb/brand_speedin/inspo-ankhway-530am-alarm.mp4', 'Ankhway (inspiration)', 'Start in bed with your alarm going off in the dark, then sit on the edge of the bed and talk about your early mornings while you put a Speedin Energy strip on. End walking out the door.', '3406b96aa44127dd', 1, 1, 13);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('debf04a858bf8f98', 'brand_speedin', '61450a9ce3dda95a', 0, 0, 14, 'live', 'Night shift hack unlocked', 'Night shift workers instantly see themselves, and the uniform tells the story.', 'Nurses, shift workers, first responders', 'Sleep', 'Shift worker tip', '["Night shift people, this one is for you.", "Trying to sleep at 10am is a nightmare.", "I wish I had this when I started nights."]', '[{"label": "Open · 0 to 3s", "text": "Scrubs on, bedroom, first line with text on screen."}, {"label": "Middle", "text": "Talk about bright daylight and noise. Close the curtains, open a strip, put it on."}, {"label": "Close", "text": "Get into bed. Say how you feel when you wake up for your next shift."}]', 'You in scrubs pointing at the camera, text: Night shift hack unlocked', 'You close the blackout curtains and the strip goes on', '[{"brand": "Manta Sleep", "what": "In your scrubs or work uniform after a night shift, tell us how hard it is to sleep at 10am when the world is awake, then put a Speedin Sleep strip on before you get into bed.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('ef8bac3a1fca9a46', 'brand_speedin', 'debf04a858bf8f98', 'upload', 'amb/brand_speedin/inspo-manta-night-nurse.mp4', 'Manta Sleep (inspiration)', 'In your scrubs or work uniform after a night shift, tell us how hard it is to sleep at 10am when the world is awake, then put a Speedin Sleep strip on before you get into bed.', '61450a9ce3dda95a', 1, 1, 14);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('8577e1a516da2764', 'brand_speedin', 'fbe68795d3f14e19', 0, 0, 15, 'live', 'My hair routine, inside and out', 'The strip slides into a routine people already love watching.', 'Beauty and hair creators', 'Hair Skin & Nails', 'Hair routine GRWM', '["My hair routine this season.", "Outside steps, then the inside step most people skip.", "Everything I do for my hair, in order."]', '[{"label": "Open · 0 to 3s", "text": "Bathroom mirror, hands in your hair, text on screen."}, {"label": "Middle", "text": "Quick clips of your real products, then towel on, strip on the tongue."}, {"label": "Close", "text": "Finished hair, hair flip, pack in hand."}]', 'Hands in your hair at the mirror, text: hair routine', 'Towel on your head, strip on your tongue', '[{"brand": "Hairburst", "what": "Film your hair routine in the bathroom: scalp, wash, towel. End with your Speedin Hair Skin & Nails strip as the inside step, then the finished hair.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('e78262720dba8d08', 'brand_speedin', '8577e1a516da2764', 'upload', 'amb/brand_speedin/inspo-hairburst-hair-routine.mp4', 'Hairburst (inspiration)', 'Film your hair routine in the bathroom: scalp, wash, towel. End with your Speedin Hair Skin & Nails strip as the inside step, then the finished hair.', 'fbe68795d3f14e19', 1, 1, 15);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('6c13ad514988b009', 'brand_speedin', '6832e83cd52b3700', 0, 0, 16, 'live', 'Reply to a comment: what is actually in it?', 'Answering a real question feels helpful, and people stay for the answer.', 'Anyone, no face needed', 'Any strip', 'Comment reply, hands only', '["Replying to the comment asking how a strip even works.", "You asked what is in it, so here is the back of the pack.", "Yes, it really melts. Watch."]', '[{"label": "Open · 0 to 3s", "text": "Comment bubble on screen, pack in your hands."}, {"label": "Middle", "text": "Flip to the label, point at the key ingredients, peel a strip and show how thin it is."}, {"label": "Close", "text": "Strip on your fingertip next to the pack. Say: 30 strips, one a day."}]', 'Comment bubble on screen over your hands holding the pack', 'Close up on the label with your finger on the line that matters', '[{"brand": "Shameless Snacks", "what": "Reply to a real comment (like: wait, how does a strip work?) with the comment bubble on screen. Hands only: show the pack, flip it, point at the label, peel a strip.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('01f8be5b7470e40c', 'brand_speedin', '6c13ad514988b009', 'upload', 'amb/brand_speedin/inspo-shameless-comment-reply.mp4', 'Shameless Snacks (inspiration)', 'Reply to a real comment (like: wait, how does a strip work?) with the comment bubble on screen. Hands only: show the pack, flip it, point at the label, peel a strip.', '6832e83cd52b3700', 1, 1, 16);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('1c6a647c521ab0ff', 'brand_speedin', '3406b96aa44127dd', 0, 0, 17, 'live', 'Two things that never leave my bag', 'The two things list makes people wait for the second item.', 'Gym goers, pickleball and golf players, coaches, runners', 'Energy', 'What''s in my bag', '["Two things that never leave my gym bag.", "I am at the court 5 days a week and these two always come with me.", "Thing one is obvious. Thing two is not."]', '[{"label": "Open · 0 to 3s", "text": "Phone low on the floor, you crouched over your bag holding your gear."}, {"label": "Middle", "text": "Put the gear down, pull out the Speedin pack, show a strip, put one on before you play."}, {"label": "Close", "text": "Toss the pack back in the bag and walk into your session."}]', 'Low angle, you holding your main piece of gear up to the lens', 'The second thing comes out and it is tiny', '[{"brand": "Infraredi", "what": "Crouch next to your gym bag, sports bag or work bag and say: two things that never leave my bag. Pull out your gear, then your Speedin Energy strips, and say when you use them.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('03c3137e71fd7fb0', 'brand_speedin', '1c6a647c521ab0ff', 'upload', 'amb/brand_speedin/inspo-infraredi-bag-two-things.mp4', 'Infraredi (inspiration)', 'Crouch next to your gym bag, sports bag or work bag and say: two things that never leave my bag. Pull out your gear, then your Speedin Energy strips, and say when you use them.', '3406b96aa44127dd', 1, 1, 17);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('2d2b24b04853c664', 'brand_speedin', '61450a9ce3dda95a', 0, 0, 18, 'live', 'Try this before bed if your mind will not stop', 'A simple routine is easy to copy, so people save it.', 'Women 40 plus, readers, anyone with a racing mind at night', 'Sleep', 'Bedtime routine tip', '["If your mind will not shut off at night, try this.", "Work, random conversations, tomorrow''s to do list. Sound familiar?", "Here is my whole wind down. It takes ten minutes."]', '[{"label": "Open · 0 to 3s", "text": "Sitting up in bed, first line, soft lamp light."}, {"label": "Middle", "text": "Show the Sleep pack, put a strip on, put your phone face down, open your book."}, {"label": "Close", "text": "Say this is the routine that works for you. Lamp off."}]', 'You sitting up in bed, robe on, talking low like it is late', 'The book comes out and the voice drops to a whisper', '[{"brand": "Budpop", "what": "Sit up in bed in your robe or pajamas and walk us through your wind down: Speedin Sleep strip, phone away, a few pages of a book. Calm voice, one take.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('648af66a7e707731', 'brand_speedin', '2d2b24b04853c664', 'upload', 'amb/brand_speedin/inspo-budpop-mind-wont-stop.mp4', 'Budpop (inspiration)', 'Sit up in bed in your robe or pajamas and walk us through your wind down: Speedin Sleep strip, phone away, a few pages of a book. Calm voice, one take.', '61450a9ce3dda95a', 1, 1, 18);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('8eaa0160a7095325', 'brand_speedin', 'fbe68795d3f14e19', 0, 0, 19, 'live', 'Why I started taking collagen', 'A personal reason makes the product feel chosen, not sold.', 'Women 45 plus, real stories', 'Hair Skin & Nails', 'Storytime at the counter', '["A couple of years ago I cut my hair way too short and hated it.", "As a woman my age, this stuff matters to me.", "I never thought about collagen until this happened."]', '[{"label": "Open · 0 to 3s", "text": "Kitchen counter, pack up, first line."}, {"label": "Middle", "text": "Tell your story. Show the strip, put it on, sip your coffee."}, {"label": "Close", "text": "Say it is the easiest thing in your morning. Pack to camera."}]', 'You holding the pack up next to your face with your coffee mug in frame', 'The strip goes on while the coffee is in your other hand', '[{"brand": "NativePath", "what": "Sitting at your kitchen counter, tell the story of why you started caring about your hair and skin, then show the Speedin Hair Skin & Nails pack and how you take it with your morning coffee.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('61771040982c8ebd', 'brand_speedin', '8eaa0160a7095325', 'upload', 'amb/brand_speedin/inspo-nativepath-collagen-coffee.mp4', 'NativePath (inspiration)', 'Sitting at your kitchen counter, tell the story of why you started caring about your hair and skin, then show the Speedin Hair Skin & Nails pack and how you take it with your morning coffee.', 'fbe68795d3f14e19', 1, 1, 19);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('342a2bafcbc35ba8', 'brand_speedin', '6832e83cd52b3700', 0, 0, 20, 'live', 'My old morning drink build vs one strip', 'Watching a long build makes one strip feel like a relief.', 'Coffee lovers, kitchen creators', 'Energy', 'Kitchen build, then the swap', '["This used to be my morning. Every step.", "First, two scoops. Then the frother. Then...", "I timed my old morning drink. Eight minutes."]', '[{"label": "Open · 0 to 3s", "text": "Wide kitchen shot, jars everywhere, first line."}, {"label": "Middle", "text": "Speed through the steps with a word on screen for each. Then stop."}, {"label": "Close", "text": "Peel a strip, put it on, grab your keys. You can still drink coffee for the taste, say the strip is your energy now."}]', 'Counter full of jars and a frother, you mid scoop', 'You stop halfway, push it all aside and pick up the strip', '[{"brand": "Everyday Dose", "what": "Film the full ritual of your old morning drink (scoops, frother, creamer, the mess), talking through every step. Then show your new morning: one Speedin Energy strip, done.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('eff86eb3dc03b1ed', 'brand_speedin', '342a2bafcbc35ba8', 'upload', 'amb/brand_speedin/inspo-dose-coffee-build.mp4', 'Everyday Dose (inspiration)', 'Film the full ritual of your old morning drink (scoops, frother, creamer, the mess), talking through every step. Then show your new morning: one Speedin Energy strip, done.', '6832e83cd52b3700', 1, 1, 20);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('fc7de2bc523f6d09', 'brand_speedin', '3406b96aa44127dd', 0, 0, 21, 'live', 'I regret buying my boyfriend this', 'A fake complaint is a fun way to say it works.', 'Creators with a partner, gift angle', 'Energy', 'Fake regret, talking head', '["I bought this for my boyfriend and honestly I regret it.", "Do not buy your husband these.", "This was supposed to be a gift. Now I have a problem."]', '[{"label": "Open · 0 to 3s", "text": "Kitchen counter, pack in hand, say the first line straight faced."}, {"label": "Middle", "text": "Explain his old routine (two coffees, cans in the truck) and that he just puts a strip on now."}, {"label": "Close", "text": "The punchline: now he is up and done before you. Hold up the pack."}]', 'You holding the pack with a serious face', 'The twist: what actually changed for your partner', '[{"brand": "Tradesman Nutrition", "what": "Stand in your kitchen with the Speedin pack and say you regret buying it for your partner, because now they are up before you every morning. Keep it playful, one take.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('8262dd40929ce570', 'brand_speedin', 'fc7de2bc523f6d09', 'upload', 'amb/brand_speedin/inspo-tradesman-boyfriend-regret.mp4', 'Tradesman Nutrition (inspiration)', 'Stand in your kitchen with the Speedin pack and say you regret buying it for your partner, because now they are up before you every morning. Keep it playful, one take.', '3406b96aa44127dd', 1, 1, 21);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('20ad499d8494eabd', 'brand_speedin', 'fbe68795d3f14e19', 0, 0, 22, 'live', 'Nobody warned me about this', 'Nobody warned me pulls in everyone it happened to.', 'Women 30 plus, busy moms (not pregnant or nursing)', 'Hair Skin & Nails', 'Storytime talking head', '["Nobody warned me about what a stressful year does to your hair.", "I am taking care of everyone else. This is my one thing for me.", "No one tells you this part."]', '[{"label": "Open · 0 to 3s", "text": "Talking head, hand in your hair, first line."}, {"label": "Middle", "text": "Explain the busy life. Show the strip and put it on. Say it is one step, no new routine."}, {"label": "Close", "text": "Back to camera, calm. Say this is the one small thing you do for you."}]', 'You holding your hair up, frustrated face', 'Quick cut to you outside with your coffee, the strip already on', '[{"brand": "Pique", "what": "Talk to camera about the hair and skin change nobody warned you about (stress, a busy year, getting older), touch your hair, then show the one easy thing you added: a Speedin Hair Skin & Nails strip.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('bb027776641cda46', 'brand_speedin', '20ad499d8494eabd', 'upload', 'amb/brand_speedin/inspo-pique-nobody-warned.mp4', 'Pique (inspiration)', 'Talk to camera about the hair and skin change nobody warned you about (stress, a busy year, getting older), touch your hair, then show the one easy thing you added: a Speedin Hair Skin & Nails strip.', 'fbe68795d3f14e19', 1, 1, 22);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('fb984876622ca761', 'brand_speedin', '6832e83cd52b3700', 0, 0, 23, 'live', 'My bag does not need to sound like a maraca', 'The rattle sound is a hook people hear before they see it.', 'Anyone, no face needed', 'Any strip', 'Hands only swap', '["My bag does not need to sound like a maraca every time I move.", "Listen to this.", "Swapping my whole pill situation for this."]', '[{"label": "Open · 0 to 3s", "text": "Shake the bag right at the mic. Text on screen."}, {"label": "Middle", "text": "Pull out each bottle and line them up. Slide the Speedin pack in."}, {"label": "Close", "text": "Shake the bag again: silence. Zip it up."}]', 'A purse being shaken, pill bottles rattling', 'Bottles come out, one flat pack goes in, bag is quiet', '[{"brand": "Emmafy", "what": "Shake your bag so we hear the pill bottles rattle, then swap them for the flat Speedin pack. Hands only, filmed in your car or at your desk.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('3be2c5e45f291e90', 'brand_speedin', 'fb984876622ca761', 'upload', 'amb/brand_speedin/inspo-emmafy-bag-rattle.mp4', 'Emmafy (inspiration)', 'Shake your bag so we hear the pill bottles rattle, then swap them for the flat Speedin pack. Hands only, filmed in your car or at your desk.', '6832e83cd52b3700', 1, 1, 23);
